"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["95971"],{43862(o){o.exports=JSON.parse('{"registro":{"codigo":"uniplus.formulario_portavel.estrutura_invalida","status":422,"titulo":"As regras n\xe3o formam um formul\xe1rio: elemento nulo, c\xf3digo repetido ou refer\xeancia que n\xe3o existe"},"descricao":{"codigo":"uniplus.formulario_portavel.estrutura_invalida","requisitos":[],"oQueAconteceu":["A avalia\xe7\xe3o de um formul\xe1rio sem cadastro confere as regras de um formul\xe1rio apresentado contra respostas simuladas, sem gravar nada nem registrar o conte\xfado enviado. As regras recebidas t\xeam um defeito de estrutura que impede formar o formul\xe1rio. Os casos s\xe3o estes, cada um com a pr\xf3pria mensagem: um elemento nulo dentro de uma lista, como \\"O elemento \'`{caminho\\\\}`\' das regras \xe9 nulo.\\", com o caminho do elemento, por exemplo `paginas[0].itens[2]`; uma p\xe1gina, um grupo, um campo, um termo, um resumo de grupo ou uma deriva\xe7\xe3o sem c\xf3digo; um c\xf3digo repetido, como \\"O c\xf3digo \'`{c\xf3digo\\\\}`\' aparece mais de uma vez como p\xe1gina.\\", e do mesmo modo entre termos e entre fatos produzidos ou grupos do formul\xe1rio (campos, deriva\xe7\xf5es, resumos de grupo e grupos dividem o mesmo conjunto de c\xf3digos); os limites de ocorr\xeancias de um grupo incoerentes, com m\xednimo negativo, ou m\xe1ximo informado menor que 1 ou menor que o m\xednimo; um formato de texto que n\xe3o \xe9 do vocabul\xe1rio do cat\xe1logo; e um resumo sobre um grupo que o formul\xe1rio n\xe3o tem.","A recusa vem no corpo da resposta, com o c\xf3digo e o `detail` que traz a mensagem, sem lista `errors`. As regras recebidas s\xe3o lidas por inteiro antes da avalia\xe7\xe3o, e a leitura para na primeira recusa, nesta ordem: o elemento nulo, as p\xe1ginas (com os itens e os grupos de cada uma), os termos, as deriva\xe7\xf5es, os resumos de grupo e, por fim, o conjunto.","As propriedades de texto que o corpo n\xe3o pode omitir, como o c\xf3digo, a obrigatoriedade e a opera\xe7\xe3o, ausentes ou nulas, s\xe3o recusadas antes, com 400 e sem c\xf3digo deste cat\xe1logo, pela leitura do corpo."],"comoResolver":["Corrija o trecho indicado na mensagem nas regras enviadas e repita a avalia\xe7\xe3o. Um c\xf3digo repetido se resolve dando c\xf3digos distintos, e o limite de ocorr\xeancias de um grupo deve ter m\xednimo de zero para cima e, quando houver m\xe1ximo, ele deve ser pelo menos 1 e n\xe3o menor que o m\xednimo."],"ondeAparece":["Avalia\xe7\xe3o de formul\xe1rio sem cadastro"]},"modulo":{"id":"transversais","nome":"Erros transversais","assunto":"Formulario portavel"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"3bbcc2307827ee8c6dab135295710bb856847f61"}}')}}]);